package com.jnapanam.sportszone.admin.web;import com.jnapanam.sportszone.admin.model.AuditLog;import com.jnapanam.sportszone.admin.repository.AuditLogRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;import org.springframework.security.core.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class AdminAuditFilter extends OncePerRequestFilter{private static final Set<String>MUTATING=Set.of("POST","PUT","PATCH","DELETE");private final AuditLogRepository logs;public AdminAuditFilter(AuditLogRepository l){logs=l;}@Override protected boolean shouldNotFilter(HttpServletRequest r){String p=r.getRequestURI();return !MUTATING.contains(r.getMethod())||!(p.startsWith("/api/v1/admin/")||p.startsWith("/api/v1/operations/"));}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{try{chain.doFilter(req,res);}finally{Authentication a=SecurityContextHolder.getContext().getAuthentication();UUID actor=null;if(a!=null&&a.isAuthenticated())try{actor=UUID.fromString(a.getName());}catch(Exception ignored){}try{logs.save(new AuditLog(actor,req.getMethod(),req.getRequestURI(),res.getStatus(),req.getRemoteAddr()));}catch(Exception ignored){}}}}
